// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.33;

import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {Ownable2StepUpgradeable} from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {ERC2771ContextUpgradeable} from "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";
import {ContextUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {IVault} from "../interfaces/IVault.sol";
import {IERC4626VaultAdapter} from "../interfaces/IERC4626VaultAdapter.sol";
import {IStakingGauge} from "../interfaces/IStakingGauge.sol";

/// @title ERC-4626 vault adapter for the Earn gauge system
/// @notice Wraps any ERC-4626 vault into a tokenized position compatible
///         with the gauge system. The adapter exists to separate yield
///         (share-price appreciation) from principal: the gauge needs to
///         extract yield independently to forward it to voters, which the
///         underlying ERC-4626 share token cannot do because its yield is
///         baked into a single appreciating share price.
///
///         The adapter periodically harvests share-price appreciation as
///         yield (earmarked in vault shares), which the gauge then claims
///         via IVault.claimYield() and forwards to voters.
///
///         LP-choice: hold the ERC-4626 vault shares directly (= yield
///         path; yield accrues to the LP via share-price appreciation) or
///         wrap+stake via `depositAndStake` (= emissions path; yield is
///         siphoned to voters in exchange for emissions earned by
///         staking). There is intentionally no third "wrap without stake"
///         option — receipts that aren't staked have appreciation
///         siphoned away with no offsetting reward and so are strictly
///         worse than holding the underlying share.
///
///         Entry is atomic via `depositAndStake`. Exit is naturally
///         two-step (`VaultGauge.withdraw` to unstake, then
///         `adapter.withdraw` to unwrap) because the gauge has no
///         `withdrawFor(amount, owner)` action that an aggregating
///         helper could compose against.
contract ERC4626VaultAdapter is
    Initializable,
    ERC20Upgradeable,
    ReentrancyGuardUpgradeable,
    Ownable2StepUpgradeable,
    ERC2771ContextUpgradeable,
    IVault,
    IERC4626VaultAdapter
{
    using SafeERC20 for IERC20;

    /// @notice The ERC-4626 vault this adapter wraps.
    IERC4626 public override vault;

    /// @notice Vault shares earmarked as yield, pending claim.
    uint256 public override accumulatedYield;

    /// @notice Snapshot of the vault's assets-per-1e18-shares ratio at the
    ///         last harvest. Used to detect appreciation since.
    uint256 public lastShareRatio;

    /// @notice The address authorized to call claimYield(). Set to the
    ///         VaultGauge after gauge creation.
    address public gauge;

    /// @dev Virtual offset to prevent inflation attacks on the receipt
    ///      token. Same approach as ERC-4626: pretend there is 1e6
    ///      virtual shares and 1e6 virtual assets backing them.
    ///      An attacker must donate ~(V * 1e6) vault shares to steal a
    ///      victim's V-sized deposit, so the attack is unprofitable for
    ///      vaults with >= 6 decimals. Do NOT use this adapter with
    ///      vaults whose shares have fewer than 6 decimals.
    uint256 internal constant VIRTUAL_SHARES = 1e6;
    uint256 internal constant VIRTUAL_ASSETS = 1e6;

    event Deposit(
        address indexed user,
        uint256 vaultShares,
        uint256 receiptTokens
    );
    event Withdraw(
        address indexed user,
        uint256 receiptTokens,
        uint256 vaultShares
    );
    event Harvest(
        uint256 yieldShares,
        uint256 newShareRatio,
        uint256 userShares,
        uint256 last
    );
    event YieldClaimed(address indexed claimant, uint256 amount);
    event GaugeSet(address indexed gauge);

    error ZeroAmount();
    error ZeroAddress();
    error NotGauge();
    error GaugeNotSet();
    error GaugeAlreadySet();

    /// @notice Constructor sets the trusted forwarder for ERC2771
    ///         meta-transactions and disables initializers on the
    ///         implementation (the proxy is initialized separately via
    ///         `initialize`).
    /// @param _forwarder The trusted MezoForwarder address. Pass address(0)
    ///        to disable meta-transactions for this deployment.
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address _forwarder) ERC2771ContextUpgradeable(_forwarder) {
        _disableInitializers();
    }

    function initialize(
        IERC4626 _vault,
        string memory _name,
        string memory _symbol,
        address _owner
    ) public initializer {
        if (address(_vault) == address(0)) revert ZeroAddress();
        if (_owner == address(0)) revert ZeroAddress();

        __ERC20_init(_name, _symbol);
        __Ownable2Step_init();
        _transferOwnership(_owner);
        __ReentrancyGuard_init();

        vault = _vault;
        lastShareRatio = _currentShareRatio();
    }

    // ── IVault ──────────────────────────────────────────────────────────

    /// @inheritdoc IVault
    /// @dev Only callable by the authorized gauge.
    function claimYield() external override nonReentrant returns (uint256) {
        if (msg.sender != gauge) revert NotGauge();

        _harvest();

        uint256 claimed = accumulatedYield;
        if (claimed > 0) {
            accumulatedYield = 0;
            IERC20(address(vault)).safeTransfer(msg.sender, claimed);
            emit YieldClaimed(msg.sender, claimed);
        }

        return claimed;
    }

    // ── IERC4626VaultAdapter ────────────────────────────────────────────

    /// @inheritdoc IERC4626VaultAdapter
    function depositAndStake(
        uint256 amount
    ) external override nonReentrant returns (uint256 receiptTokens) {
        return _depositAndStake(amount, _msgSender());
    }

    /// @inheritdoc IERC4626VaultAdapter
    /// @dev Recipient-explicit overload. Useful for transaction bundlers
    ///      (Morpho Bundler3, account-abstraction routers) so the bundler
    ///      can call this on a user's behalf and credit the gauge stake
    ///      directly to the user rather than to itself.
    function depositAndStake(
        uint256 amount,
        address recipient
    ) external override nonReentrant returns (uint256 receiptTokens) {
        return _depositAndStake(amount, recipient);
    }

    /// @inheritdoc IERC4626VaultAdapter
    function withdraw(
        uint256 receiptAmount
    ) external override nonReentrant returns (uint256 vaultShares) {
        return _withdraw(receiptAmount, _msgSender(), _msgSender());
    }

    /// @inheritdoc IERC4626VaultAdapter
    /// @dev Receiver/owner-explicit overload. Bundlers and routers can
    ///      withdraw on behalf of `owner` (provided they hold ERC-20
    ///      allowance for the receipts) and route the underlying vault
    ///      shares to `receiver`.
    function withdraw(
        uint256 receiptAmount,
        address receiver,
        address owner
    ) external override nonReentrant returns (uint256 vaultShares) {
        return _withdraw(receiptAmount, receiver, owner);
    }

    /// @inheritdoc IERC4626VaultAdapter
    function harvest() external override nonReentrant {
        _harvest();
    }

    // ── Owner ───────────────────────────────────────────────────────────

    /// @notice Set the authorized gauge. One-shot — callable exactly once
    ///         per adapter, after which the gauge is permanently bound.
    /// @dev    Mirrors the immutable staking-token binding on the gauge
    ///         side (PoolGauge / VaultGauge): once the adapter/gauge pair
    ///         is set, users have a permanent guarantee about where yield
    ///         flows. Migration to a different gauge requires redeploying
    ///         the adapter.
    ///
    ///         Any appreciation between deployment and this call accrues
    ///         to LPs because there was no party to claim yield during
    ///         that window.
    function setGauge(address _gauge) external onlyOwner {
        if (_gauge == address(0)) revert ZeroAddress();
        if (gauge != address(0)) revert GaugeAlreadySet();

        lastShareRatio = _currentShareRatio();

        emit GaugeSet(_gauge);
        gauge = _gauge;
    }

    // ── Views ───────────────────────────────────────────────────────────

    /// @inheritdoc IVault
    function yieldToken() external view override returns (address) {
        return address(vault);
    }

    /// @notice Mirror the wrapped vault's decimals so UIs and aggregators
    ///         see consistent precision across the receipt token and the
    ///         underlying ERC-4626 share.
    function decimals() public view override returns (uint8) {
        return vault.decimals();
    }

    // ── Internals ───────────────────────────────────────────────────────

    /// @dev Core deposit logic, called only from `_depositAndStake`.
    function _deposit(
        uint256 amount,
        address receiver
    ) internal returns (uint256 receiptTokens) {
        if (amount == 0) revert ZeroAmount();
        if (receiver == address(0)) revert ZeroAddress();

        _harvest();

        uint256 userShares = _userShares();
        uint256 supply = totalSupply();
        receiptTokens =
            (amount * (supply + VIRTUAL_SHARES)) /
            (userShares + VIRTUAL_ASSETS);

        IERC20(address(vault)).safeTransferFrom(
            _msgSender(),
            address(this),
            amount
        );
        _mint(receiver, receiptTokens);

        emit Deposit(receiver, amount, receiptTokens);
    }

    /// @dev Shared depositAndStake logic. Mints receipts to the adapter
    ///      transiently, sets a one-shot allowance on itself for the gauge,
    ///      then has the gauge pull the receipts and credit `recipient`.
    ///      The allowance is fully consumed by the gauge's exact-amount
    ///      pull, so nothing lingers post-call.
    function _depositAndStake(
        uint256 amount,
        address recipient
    ) internal returns (uint256 receiptTokens) {
        if (gauge == address(0)) revert GaugeNotSet();
        if (recipient == address(0)) revert ZeroAddress();

        receiptTokens = _deposit(amount, address(this));
        _approve(address(this), gauge, receiptTokens);
        IStakingGauge(gauge).deposit(receiptTokens, recipient);
    }

    /// @dev Shared withdraw logic for both external overloads. Both wrappers
    ///      apply `nonReentrant` before reaching this helper.
    function _withdraw(
        uint256 receiptAmount,
        address receiver,
        address owner
    ) internal returns (uint256 vaultShares) {
        if (receiptAmount == 0) revert ZeroAmount();
        if (receiver == address(0)) revert ZeroAddress();
        if (owner == address(0)) revert ZeroAddress();

        if (_msgSender() != owner) {
            _spendAllowance(owner, _msgSender(), receiptAmount);
        }

        _harvest();

        uint256 supply = totalSupply();
        uint256 userShares = _userShares();
        vaultShares =
            (receiptAmount * (userShares + VIRTUAL_ASSETS)) /
            (supply + VIRTUAL_SHARES);

        _burn(owner, receiptAmount);
        IERC20(address(vault)).safeTransfer(receiver, vaultShares);

        emit Withdraw(owner, receiptAmount, vaultShares);
    }

    /// @dev Reads the current share ratio and, if it has increased above
    ///      the recorded peak (lastShareRatio), earmarks a proportional
    ///      number of held vault shares as yield.
    ///
    ///      High-water-mark semantics: depreciation events do NOT lower
    ///      lastShareRatio. Subsequent appreciation only contributes yield
    ///      once it exceeds the prior peak. This is intentional — recovery
    ///      from a loss isn't "new" yield to voters; it's the existing
    ///      principal claim becoming whole again. Example, ratio path
    ///      1.05 → 1.02 → 1.07:
    ///        - lastShareRatio stays at 1.05 throughout the dip
    ///        - On reaching 1.07, yieldShares ∝ (1.07 - 1.05) / 1.07
    ///        - The 1.02 → 1.05 recovery is invisible to the mechanism
    ///
    ///      Pre-gauge case: when no gauge is set there is no party that
    ///      can claim accumulatedYield, so this function advances the
    ///      baseline without earmarking. Pre-gauge appreciation stays in
    ///      _userShares() and accrues to LPs. See setGauge() for the
    ///      baseline-reset that runs when a gauge is first wired in.
    function _harvest() internal {
        uint256 currentRatio = _currentShareRatio();

        // Before a gauge is set, there is no party that can claim
        // accumulatedYield, so we advance the baseline without earmarking.
        // Pre-gauge appreciation stays in _userShares() and accrues to LPs.
        if (gauge == address(0)) {
            lastShareRatio = currentRatio;
            return;
        }

        uint256 last = lastShareRatio;

        if (currentRatio <= last) return;

        uint256 userShares = _userShares();
        uint256 yieldShares = (userShares * (currentRatio - last)) /
            currentRatio;

        if (yieldShares > 0) {
            accumulatedYield += yieldShares;
            emit Harvest(yieldShares, currentRatio, userShares, last);
        }

        lastShareRatio = currentRatio;
    }

    /// @dev Vault shares belonging to depositors (total balance minus yield
    ///      earmarked for the gauge).
    function _userShares() internal view returns (uint256) {
        return
            IERC20(address(vault)).balanceOf(address(this)) - accumulatedYield;
    }

    /// @dev The vault's assets-per-1e18-shares ratio. Read directly from
    ///      the vault's convertToAssets — no oracle needed because the
    ///      vault is canonical ERC-4626.
    function _currentShareRatio() internal view returns (uint256) {
        return vault.convertToAssets(1e18);
    }

    // ── ERC2771 ─────────────────────────────────────────────────────────

    /// @dev Override _msgSender to support ERC2771 meta-transactions via
    ///      MezoForwarder. Resolves the conflict between ContextUpgradeable
    ///      (inherited via ERC20Upgradeable/Ownable) and ERC2771ContextUpgradeable.
    function _msgSender()
        internal
        view
        override(ContextUpgradeable, ERC2771ContextUpgradeable)
        returns (address sender)
    {
        return ERC2771ContextUpgradeable._msgSender();
    }

    /// @dev Override _msgData to support ERC2771 meta-transactions via
    ///      MezoForwarder.
    function _msgData()
        internal
        view
        override(ContextUpgradeable, ERC2771ContextUpgradeable)
        returns (bytes calldata)
    {
        return ERC2771ContextUpgradeable._msgData();
    }

    /// @dev Override _contextSuffixLength to support ERC2771 meta-transactions
    ///      via MezoForwarder.
    function _contextSuffixLength()
        internal
        view
        override(ContextUpgradeable, ERC2771ContextUpgradeable)
        returns (uint256)
    {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }
}

