    /// @param receiver Address that receives the vault shares.
    /// @param owner Address whose receipts are burned.
    /// @return vaultShares Amount of vault share tokens returned.
    function withdraw(
        uint256 receiptAmount,
        address receiver,
        address owner
    ) external returns (uint256 vaultShares);

    /// @notice Harvest yield from share-price appreciation since last
    ///         harvest. No-op if share price has not increased.
    function harvest() external;

    /// @notice The ERC-4626 vault this adapter wraps.
    function vault() external view returns (IERC4626);

    /// @notice Vault shares earmarked as yield, pending claim by the gauge.
    function accumulatedYield() external view returns (uint256);
}

